GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU whose resulting KVPR (after placement) is lowest."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_kvpr = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] - m.model_size > 0:
                kvpr = (load[g] + m.req_rate / m.slo) / (free[g] - m.model_size)
                if kvpr < best_kvpr:
                    best_kvpr, best_idx = kvpr, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _max_kvpr(placement):
    """Compute the max KVPR of a placement."""
    mx = 0.0
    for mlist in placement.values():
        free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
        if mlist and free > 0:
            mx = max(mx, sum(m.req_rate / m.slo for m in mlist) / free)
    return mx


def compute_model_placement(gpu_num, models):
    """
    Greedy placement minimizing max KVPR: each model goes to the GPU whose
    current KVPR is lowest among GPUs that fit it. Multiple model orderings
    (pressure desc, size desc, pressure/size desc) are tried and the best
    placement (lowest max KVPR) is returned.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is not None:
            mx = _max_kvpr(p)
            if mx < best_max:
                best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")

    # Hill-climb: move or swap a model off the worst-KVPR GPU when it lowers max KVPR.
    def kvprs(p):
        return [_max_kvpr({g: p[g]}) for g in range(gpu_num)]

    for _ in range(len(models) * 2):
        k = kvprs(best)
        wg = max(range(gpu_num), key=lambda g: k[g])
        if k[wg] == 0.0:
            break
        improved = False
        for m in list(best[wg]):
            # Try moving m to another GPU.
            for g in range(gpu_num):
                if g == wg:
                    continue
                free_g = GPU_MEM_SIZE - sum(x.model_size for x in best[g])
                if m.model_size >= free_g:
                    continue
                best[wg].remove(m)
                best[g].append(m)
                if _max_kvpr(best) < max(k):
                    improved = True
                    break
                best[g].remove(m)
                best[wg].append(m)
            if improved:
                break
            # Try swapping m with a model on another GPU.
            for g in range(gpu_num):
                if g == wg:
                    continue
                for m2 in list(best[g]):
                    best[wg].remove(m)
                    best[g].remove(m2)
                    best[wg].append(m2)
                    best[g].append(m)
                    if _max_kvpr(best) < max(k):
                        improved = True
                        break
                    best[wg].remove(m2)
                    best[g].remove(m)
                    best[wg].append(m)
                    best[g].append(m2)
                if improved:
                    break
            if improved:
                break
        if not improved:
            break
    return best

